const visual = {
  prepare: function (input) {
    return [];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var margin = Math.min(w, h) * 0.08;
    var side = Math.min(w - 2 * margin, h - 2 * margin);
    var x0 = (w - side) / 2;
    var y0 = (h - side) / 2;
    var cell = side / 4;
    var paths = [];
    var children = [];
    var i;
    for (i = 0; i <= 4; i++) {
      var x = x0 + i * cell;
      var vId = 'v' + i;
      paths.push({
        id: vId,
        commands: visualSdk.polyline([{ x: x, y: y0 }, { x: x, y: y0 + side }])
      });
      children.push({ type: 'path', pathId: vId, stroke: '#26354a', strokeWidth: 1.5, fill: 'none' });
    }
    for (i = 0; i <= 4; i++) {
      var y = y0 + i * cell;
      var hId = 'h' + i;
      paths.push({
        id: hId,
        commands: visualSdk.polyline([{ x: x0, y: y }, { x: x0 + side, y: y }])
      });
      children.push({ type: 'path', pathId: hId, stroke: '#26354a', strokeWidth: 1.5, fill: 'none' });
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid-4x4',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
